from pathlib import Path
import pytest
from utils.common_methods import RUN_CONFIG, get_test_data
from framework.app import App

def pytest_configure(config):
    Path("reports").mkdir(exist_ok=True)
    Path("reports/errors.log").write_text("Playwright Python execution started\n")

def pytest_runtest_logstart(nodeid, location):
    print(f"[TEST] {nodeid}")

@pytest.hookimpl(hookwrapper=True)
def pytest_runtest_makereport(item, call):
    outcome = yield
    report = outcome.get_result()
    if report.when == "call" and report.failed:
        with Path("reports/errors.log").open("a") as log:
            log.write(f"\n[FAIL] {item.nodeid}\n{report.longreprtext}\n")

@pytest.fixture(scope="session")
def browser_type_launch_args(browser_type_launch_args):
    return {**browser_type_launch_args, "headless": RUN_CONFIG["headless"]}

@pytest.fixture(scope="session")
def browser_context_args(browser_context_args):
    return {**browser_context_args, "base_url": get_test_data().get("baseUrl", "https://www.saucedemo.com")}

